/* The resume path, and it must hold on EVERY re-run rather than only the first.

   Stage 03 routinely takes an hour and fails part-way. If a re-run re-fires
   cohorts that were already collected, it does not merely waste time: each
   trigger takes Convin's global per-tenant lock for 4-6 minutes, so re-doing
   thirteen collected cohorts blocks the tenant for an hour to achieve nothing.
   `collected` comes from stage 03's --list-cohorts, which reads state — so this
   filter is the same one a terminal re-run would apply. */

const env = $input.first().json;
const called = $('When called by the Orchestrator').first().json;
const all = env.json?.cohorts ?? [];
const todo = all.filter((c) => !c.collected);

return [{
  json: {
    month: called.month,
    dryRun: called.dryRun === true || called.dryRun === 'true',
    runId: called.runId ?? '',
    total: all.length,
    alreadyCollected: all.length - todo.length,
    todo,
  },
}];

/* One item per cohort. Split In Batches then takes them one at a time —
   Convin enforces one job per tenant server-side, so concurrency buys nothing
   and risks a mis-fire, and one cohort per iteration is what makes a stall
   visible as its own row while it is happening rather than after two hours of
   silence. */
const j = $input.first().json;
return j.todo.map((c) => ({ json: { ...c, key: c.key, month: j.month, dryRun: j.dryRun, runId: j.runId } }));

/* Attempt counter for the cohort currently in the loop.

   Two paths reach this node: a fresh cohort out of Split In Batches (no attempt
   yet → 1), and the backoff Wait on a retry (attempt N → N+1). Keeping the
   count on the item rather than in state is deliberate — the retry policy is a
   workflow concern (§3.4) and state should record what happened, not how many
   times n8n tried. */
const j = $input.first().json;
const attempt = Number(j.attempt || 0) + 1;
return [{ json: { ...j, attempt } }];

/* This cohort is done. Emit a small result that Split In Batches accumulates
   for the summary — the collection itself was already recorded in state by
   stage 04. */
const a = $('Attempt').first().json;
return [{ json: { key: a.key, campaign: a.campaign, status: 'collected', attempts: a.attempt } }];

/* Retry, or give up on this cohort and move on.

   §3.4 retries a CRASH: Convin's queue cannot be made reliable by code — one
   job failed outright, another hung 100+ minutes holding the global lock — so
   backoff and re-fire is the whole strategy. 5, 10, 20 minutes, three attempts.

   A STOP is not retried. It is the pipeline asking a human a question (a 401
   with no Playwright credentials, a subject pattern that does not match), and
   asking it again in five minutes, three times, only delays the escalation by
   35 minutes. It escalates immediately — and AMBER, because a question is not
   a fault.

   What must never happen either way: a failed export becoming "no calls". Two
   August failures looked exactly like calling had stopped, and their retries
   returned 8,250 and 9,044 rows of real activity. So the cohort is recorded as
   FAILED, never as collected-and-empty, and the month is then incomplete. */

const MAX_ATTEMPTS = 3;
const a = $('Attempt').first().json;
const env = $input.first().json;

const isStop = env.outcome === 'stop';
const attempt = Number(a.attempt || 1);
const stageJson = env.json ?? {};
const reason = stageJson.reason || env.contractViolation || (env.stderrTail || '').slice(-400) || 'no reason reported';

const retry = !isStop && attempt < MAX_ATTEMPTS;
const waitMinutes = 5 * Math.pow(2, attempt - 1); // 5 · 10 · 20

return [{
  json: {
    ...a,
    retry,
    waitMinutes,
    attempt,
    failedStage: env.stage,
    outcome: env.outcome,
    reason,
    severity: isStop ? 'stop' : 'fail',
    escalationTitle: isStop
      ? 'cohort ' + a.key + ' needs a decision'
      : 'cohort ' + a.key + ' failed after ' + attempt + ' attempt(s)',
    escalationBody: [
      (isStop ? 'Stopped' : 'Crashed') + ' at stage ' + env.stage + ' on cohort ' + a.key + ', attempt ' + attempt + ' of ' + MAX_ATTEMPTS + '.',
      '',
      reason,
      '',
      isStop
        ? 'This is a question, not a fault. The other cohorts continue.'
        : 'The other cohorts continue. This one is recorded as FAILED, not as a cohort with no calls — a failed export must never be read as "nobody was dialled".',
      '',
      'The month will be treated as INCOMPLETE, and stages 05-07 will not run until this is resolved.',
    ].join('\n'),
  },
}];

/* Record the failure in state/<month>.json. Quoting discipline as everywhere
   else: the only place a value reaches a shell is a Code node that quotes every
   token. */
const j = $input.first().json;
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — see n8n/SETUP_MONTH_PIPELINE.md');

const reason = 'stage ' + j.failedStage + ' ' + j.outcome + ' after ' + j.attempt + ' attempt(s): ' + String(j.reason).slice(0, 300);

const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage 03 --month ' + q(j.month)
  + ' --cohort ' + q(j.key)
  + ' --mark-failed --reason ' + q(reason)
  + ' --json';

return [{ json: { ...j, command, markReason: reason } }];

/* Marked failed and escalated. Continue with the remaining cohorts: one stuck
   cohort must not cost the other thirteen (§3.4). */
const j = $('Decide retry').first().json;
return [{ json: { key: j.key, campaign: j.campaign, status: 'failed', attempts: j.attempt, outcome: j.outcome, reason: j.reason } }];

/* What the Orchestrator acts on.

   §3.4 step 6: if any cohort ended failed, the month is INCOMPLETE and stages
   05-08 must not run. Building a report on a month where one cohort's calls
   never arrived produces a book whose AI figures are silently short — which is
   the exact shape of wrongness this pipeline exists to refuse. */
const called = $('When called by the Orchestrator').first().json;
const picked = $('Pick the uncollected').first().json;

const items = $input.all().map((i) => i.json).filter((i) => i && i.status);
const collected = items.filter((i) => i.status === 'collected');
const failed = items.filter((i) => i.status === 'failed');

const monthIncomplete = failed.length > 0;

return [{
  json: {
    ok: !monthIncomplete,
    month: called.month,
    runId: called.runId ?? '',
    dryRun: picked.dryRun === true,
    cohorts: picked.total,
    alreadyCollected: picked.alreadyCollected,
    attempted: items.length,
    collected: collected.length,
    failed: failed.map((f) => ({ key: f.key, outcome: f.outcome, attempts: f.attempts, reason: f.reason })),
    monthIncomplete,
    reason: monthIncomplete
      ? failed.length + ' of ' + items.length + ' cohort(s) failed — the month is incomplete and stages 05-07 must not run on it'
      : items.length === 0
        ? 'every cohort was already collected — nothing to do'
        : 'all ' + collected.length + ' cohort(s) collected',
  },
}];

/* Stage 03 --list-cohorts did not return a list, so there is nothing to loop
   over and no way to tell what is outstanding. Usually: stage 02 has not
   produced a plan yet. */
const env = $input.first().json;
const called = $('When called by the Orchestrator').first().json;
const stageJson = env.json ?? {};
return [{
  json: {
    ok: false,
    month: called.month,
    runId: called.runId ?? '',
    cohorts: 0, collected: 0, failed: [], attempted: 0,
    monthIncomplete: true,
    outcome: env.outcome,
    reason: 'could not list cohorts (stage 03 --list-cohorts ' + env.outcome + '): ' + (stageJson.reason || env.contractViolation || env.stderrTail || 'no reason reported'),
  },
}];
